UPDATE booking_slot
SET sold_stock = sold_stock + #{quantity}
WHERE id = #{slotId}
  AND status = 1
  AND sold_stock + #{quantity} <= total_stock

UPDATE booking_slot
SET sold_stock = sold_stock - #{quantity}
WHERE id = #{slotId}
  AND sold_stock >= #{quantity}

UPDATE booking_slot
SET total_stock = #{totalStock}
WHERE id = #{slotId}
  AND sold_stock <= #{totalStock}
